ST.xhtml:
// --------------------------------------------------
// 主逻辑
// --------------------------------------------------
// 五轴使能由 AxisEnableControl_PRG 根据 arReg_data[32] 统一控制。
// 这里不再每周期强制 TRUE，避免覆盖寄存器关闭使能命令。
// v26086：arAi_data[9] 五轴运行状态输入寄存器改由 ModbusTcpSlave 统一写出。
// 本程序只维护内部状态变量 bfiveDOF_state。
// 检测外部移动指令
trig_start(CLK := Move_5Axis_Sign=1);
IF trig_start.Q THEN

	log_msg := 'five-axis platform starts moving';
// 	logfb(write:=TRUE,sFileTestString:=log_msg);
	AppendLog(log_msg);

    // 使能所有轴（可放在这里一次性使能）
	bfiveDOF_state:=1;//开始运动
    AppendLog('status 0:6-axis start move' );
    step := 10;   // 开始安全顺序
END_IF

CASE step OF
    0: // 空闲
		bfiveDOF_state:=0;//开始运动
    // ---------- 阶段1：轴移动到目标 ----------
    10:
		FOR i := 1 TO AXIS_COUNT DO
			final_angle[i] := PlatformTargetAngle[i];
			final_vel[i]   := 360*6000/60;
			Axes[i].AxisDone := FALSE;  
			GVL.Axes[i].NeedMoveAxis := TRUE;
		END_FOR
        fbMove_2(AxisAngle := final_angle, AxisVel := final_vel, Execute := TRUE,Monitor:=TRUE);
        step := 20;

		log_msg := 'State 20: Start moving XYABC AXIS... ';
// 		logfb(write:=TRUE,sFileTestString:=log_msg);
		AppendLog(log_msg);;
    20:
        fbMove_2(AxisAngle := final_angle, AxisVel := final_vel, Execute := FALSE,Monitor:=TRUE);
        IF fbMove_2.allDone THEN
			log_msg := 'State 21: XYZABC AXIS movement completed';
// 			logfb(write:=TRUE,sFileTestString:=log_msg);
			AppendLog(log_msg);
        ELSIF fbMove_2.Error THEN
            bfiveDOF_state:=2;
        END_IF
		step := 0;



END_CASE

// v26086：本程序只读取 SoftMotion 状态并写入全局缓存。
// 所有 arReg_data 寄存器地址统一在 ModbusTcpSlave 中写出，方便集中排查。

fbStatusX(
    Axis := AXIS_X,
    Enable := TRUE,
    Valid => ,
    Busy => ,
    Error => bStatusErrorX,
    ErrorID => eStatusErrorX,
    Disabled => ,
    Errorstop => ,
    Stopping => ,
    StandStill => ,
    DiscreteMotion => ,
    ContinuousMotion => ,
    SynchronizedMotion => ,
    Homing => ,
    ConstantVelocity => ,
    Accelerating => ,
    Decelerating => ,
    FBErrorOccured => bStatusFBErrorX,
);

// 读取 X 轴本体错误。这里不直接写 arReg_data，寄存器统一由 ModbusTcpSlave 输出。
fbAxisErrorX(
    Axis := AXIS_X,
    Enable := TRUE,
    Valid => ,
    Busy => ,
    Error => bAxisReadErrorX,
    ErrorID => eAxisReadErrorX,
    AxisError => bAxisErrorX,
    AxisErrorID => dwAxisErrorX,
    SWEndSwitchActive => bSwEndSwitchX
);
IF NOT bAxisErrorX THEN
    // 无轴本体错误时清零 AxisErrorID 缓存，避免保留上一次错误号。
    dwAxisErrorX := DWORD#0;
END_IF;

// 把 X 轴状态压缩成 WORD 缓存。实际 arReg_data[33] 由 ModbusTcpSlave 写出。
wStatusX := WORD#0;
IF fbStatusX.Disabled THEN wStatusX := wStatusX OR WORD#16#0001; END_IF;
IF fbStatusX.Errorstop THEN wStatusX := wStatusX OR WORD#16#0002; END_IF;
IF fbStatusX.Stopping THEN wStatusX := wStatusX OR WORD#16#0004; END_IF;
IF fbStatusX.StandStill THEN wStatusX := wStatusX OR WORD#16#0008; END_IF;
IF fbStatusX.DiscreteMotion THEN wStatusX := wStatusX OR WORD#16#0010; END_IF;
IF fbStatusX.ContinuousMotion THEN wStatusX := wStatusX OR WORD#16#0020; END_IF;
IF fbStatusX.SynchronizedMotion THEN wStatusX := wStatusX OR WORD#16#0040; END_IF;
IF fbStatusX.Homing THEN wStatusX := wStatusX OR WORD#16#0080; END_IF;
IF fbStatusX.ConstantVelocity THEN wStatusX := wStatusX OR WORD#16#0100; END_IF;
IF fbStatusX.Accelerating THEN wStatusX := wStatusX OR WORD#16#0200; END_IF;
IF fbStatusX.Decelerating THEN wStatusX := wStatusX OR WORD#16#0400; END_IF;
IF bAxisErrorX THEN wStatusX := wStatusX OR WORD#16#4000; END_IF;
IF bSwEndSwitchX THEN wStatusX := wStatusX OR WORD#16#8000; END_IF;
wAxisStatusReg[1] := wStatusX;

// 错误号先放入全局缓存，ModbusTcpSlave 统一拆成低/高 16 位寄存器。
dwAxisErrorIDReg[1] := dwAxisErrorX;
dwReadStatusErrorIDReg[1] := TO_DWORD(eStatusErrorX);
dwReadAxisErrorFBIDReg[1] := TO_DWORD(eAxisReadErrorX);

