wReadStatusFBErrorBitsReg := wStatusFBErrorFeedback;

//------------------------------------------------------------------
// Z 轴控制逻辑（简化版 - 仅上升沿触发）
//------------------------------------------------------------------

// 读取实际位置
伺服实际位置(
    Axis    := AXIS_X,
    Enable  := TRUE,
    Position=> 当前位置
);
GVL.Axes[1].ActualAngle := 当前位置;

// 读取轴状态
伺服状态(
    Axis    := AXIS_X,
    Enable  := TRUE,
    Valid   => ,
    Busy    => ,
    Error   => 伺服错误状态,
    ErrorID => ,
    Disabled=> 总线状态
);

// 轴使能控制
伺服使能(
    Axis               := AXIS_X,
    Enable             := TRUE,
    bRegulatorOn       := GVL.Axes[1].AxisEnable,
    bDriveStart        := GVL.Axes[1].AxisEnable,
    Status             => 轴使能状态,
    bRegulatorRealState=> ,
    bDriveStartRealState=> ,
    Busy               => ,
    Error              => bPowerErrorDiag,
    ErrorID            => ePowerErrorDiag
);



// v26086：本轴 MC_Power 诊断先写入全局缓存，实际寄存器输出统一由 ModbusTcpSlave 完成。
dwPowerErrorIDReg[1] := TO_DWORD(ePowerErrorDiag);

// wPowerDiagReg[1] bit0=MC_Power.Status，bit1=MC_Power.Error。
wPowerDiag := WORD#0;
IF 轴使能状态 THEN wPowerDiag := wPowerDiag OR WORD#16#0001; END_IF;
IF bPowerErrorDiag THEN wPowerDiag := wPowerDiag OR WORD#16#0002; END_IF;
wPowerDiagReg[1] := wPowerDiag;

// 目标位置、速度赋值（来自全局变量）
目标位置 := GVL.Axes[1].TargetAngle;
目标速度 :=  GVL.Axes[1].TargetVel;

// ********** 核心：上升沿触发运动 **********
// 使用 R_TRIG 检测 need_move 的上升沿
move_trigger(CLK := GVL.Axes[1].NeedMoveAxis);
IF move_trigger.Q THEN
    AXIS_X_EXCUSE := TRUE;   // 产生一个扫描周期的脉冲
	log_msg := 'X-axis has been triggered';
// 	logfb(write:=TRUE,sFileTestString:=log_msg);
	AppendLog(log_msg);
ELSE
    AXIS_X_EXCUSE := FALSE;
END_IF

// 绝对定位指令
GVL.Axes[1].伺服绝对位置执行(
    Axis        := AXIS_X,
    Execute     := AXIS_X_EXCUSE,
    Position    := 目标位置,
    Velocity    := 目标速度,
    Acceleration:= 10000,//4000  //85000
    Deceleration:= 10000,//4000  //85000
    Jerk        := ,
    Direction   := ,
    BufferMode  := ,
    Done        => GVL.Axes[1].InitDone,
    Busy        => ,
    Active      => ,
    CommandAborted=> ,
    Error       => GVL.Axes[1].AxisError,
    ErrorID     =>
);

// 运动完成：清除 need_move 并通知状态机
IF  GVL.Axes[1].InitDone THEN
    GVL.Axes[1].NeedMoveAxis := FALSE;              // 清除运动请求
    GVL.Axes[1].AxisDone := TRUE;         // 通知状态机运动完成
	log_msg := 'X-Axis movement completed! ';
// 	logfb(write:=TRUE,sFileTestString:=log_msg);
// 	AppendLog(log_msg);
END_IF

// 复位功能块（保持不变）
伺服复位(
    Axis    := AXIS_X,
    Execute := 复位中 AND NOT 伺服复位.Done,
    Done    => ,
    Busy    => ,
    Error   => ,
    ErrorID =>
);

复位轴组(
    Axis      := AXIS_X,
    bExecute  := 伺服复位.Done,
    bVirtual  := FALSE,
    bDone     => ,
    bBusy     => ,
    bError    => ,
    nErrorID  =>
);

// 报警清除逻辑
复位触发(CLK := (伺服错误状态 OR 复位请求) AND NOT 复位中);
IF 复位触发.Q THEN
    复位中 := TRUE;
    复位请求 := FALSE;
END_IF

IF 伺服复位.Done THEN
    复位中 := FALSE;
END_IF

