// ================================
  // 5轴点动控制
  // ================================

  // 五轴总关闭时，点动功能块不会继续用本地 TRUE 保持上使能。

  // v26086：复位命令由 ModbusTcpSlave 从 arReg_data[89] 解析到 xJogReset[1]。
  // FB_ServoJog 内部用 R_TRIG 把这个 BOOL 转成 MC_Reset 上升沿。
  xResetCmdReg := xJogReset[1];

  xServoEnable := GVL.Axes[1].AxisEnable;

  fbJogX(
      Axis := AXIS_X,
      xServoOn := xServoEnable,
      xReset := xResetCmdReg,
      xJogFwd := xJogFwd[1],
      xJogRev := xJogRev[1],
      xLimitFwd := FALSE,
      xLimitRev := FALSE,
      lrJogVel := 100.0,
      lrAcc := 100.0,
      lrDec := 200.0,
      lrJerk := 0.0
  );


  // v26086：Jog 程序只写全局反馈位图，寄存器 arReg_data[90..99] 统一由 ModbusTcpSlave 写出。
  IF xResetCmdReg THEN
    wJogResetCmdReg := wJogResetCmdReg OR WORD#16#0001;
ELSE
    wJogResetCmdReg := wJogResetCmdReg AND WORD#16#FFFE;
END_IF;
  IF xJogMode[1] THEN
    wJogModeReg := wJogModeReg OR WORD#16#0001;
ELSE
    wJogModeReg := wJogModeReg AND WORD#16#FFFE;
END_IF;
  IF xJogFwd[1] THEN
    wJogFwdReg := wJogFwdReg OR WORD#16#0001;
ELSE
    wJogFwdReg := wJogFwdReg AND WORD#16#FFFE;
END_IF;
  IF xJogRev[1] THEN
    wJogRevReg := wJogRevReg OR WORD#16#0001;
ELSE
    wJogRevReg := wJogRevReg AND WORD#16#FFFE;
END_IF;
  IF fbJogX.xReady THEN
    wJogReadyReg := wJogReadyReg OR WORD#16#0001;
ELSE
    wJogReadyReg := wJogReadyReg AND WORD#16#FFFE;
END_IF;
  IF fbJogX.xMoving THEN
    wJogMovingReg := wJogMovingReg OR WORD#16#0001;
ELSE
    wJogMovingReg := wJogMovingReg AND WORD#16#FFFE;
END_IF;
  IF fbJogX.xFault THEN
    wJogFaultReg := wJogFaultReg OR WORD#16#0001;
ELSE
    wJogFaultReg := wJogFaultReg AND WORD#16#FFFE;
END_IF;
  IF fbJogX.xJogError THEN
    wJogErrorReg := wJogErrorReg OR WORD#16#0001;
ELSE
    wJogErrorReg := wJogErrorReg AND WORD#16#FFFE;
END_IF;
  IF fbJogX.xJogAborted THEN
    wJogAbortedReg := wJogAbortedReg OR WORD#16#0001;
ELSE
    wJogAbortedReg := wJogAbortedReg AND WORD#16#FFFE;
END_IF;

