  IF fbJogZ.xReady THEN
    wJogReadyReg := wJogReadyReg OR WORD#16#0004;
ELSE
    wJogReadyReg := wJogReadyReg AND WORD#16#FFFB;
END_IF;
  IF fbJogZ.xMoving THEN
    wJogMovingReg := wJogMovingReg OR WORD#16#0004;
ELSE
    wJogMovingReg := wJogMovingReg AND WORD#16#FFFB;
END_IF;
  IF fbJogZ.xFault THEN
    wJogFaultReg := wJogFaultReg OR WORD#16#0004;
ELSE
    wJogFaultReg := wJogFaultReg AND WORD#16#FFFB;
END_IF;
  IF fbJogZ.xJogError THEN
    wJogErrorReg := wJogErrorReg OR WORD#16#0004;
ELSE
    wJogErrorReg := wJogErrorReg AND WORD#16#FFFB;
END_IF;
  IF fbJogZ.xJogAborted THEN
    wJogAbortedReg := wJogAbortedReg OR WORD#16#0004;
ELSE
    wJogAbortedReg := wJogAbortedReg AND WORD#16#FFFB;
END_IF;

// ================================
  // 5轴点动控制
  // ================================


  // 五轴总关闭时，点动功能块不会继续用本地 TRUE 保持上使能。

  // v26086：复位命令由 ModbusTcpSlave 从 arReg_data[89] 解析到 xJogReset[4]。
  // FB_ServoJog 内部用 R_TRIG 把这个 BOOL 转成 MC_Reset 上升沿。
  xResetCmdReg := xJogReset[4];

  xServoEnable := GVL.Axes[4].AxisEnable;

  fbJogB(
      Axis := AXIS_B,
      xServoOn := xServoEnable,
      xReset := xResetCmdReg,
      xJogFwd := xJogFwd[4],
      xJogRev := xJogRev[4],
      xLimitFwd := FALSE,
      xLimitRev := FALSE,
      lrJogVel := 100.0,
      lrAcc := 100.0,
      lrDec := 200.0,
      lrJerk := 0.0
  );


  // v26086：Jog 程序只写全局反馈位图，寄存器 arReg_data[90..99] 统一由 ModbusTcpSlave 写出。
  IF xResetCmdReg THEN
    wJogResetCmdReg := wJogResetCmdReg OR WORD#16#0008;
ELSE
    wJogResetCmdReg := wJogResetCmdReg AND WORD#16#FFF7;
END_IF;
  IF xJogMode[4] THEN
    wJogModeReg := wJogModeReg OR WORD#16#0008;
ELSE
    wJogModeReg := wJogModeReg AND WORD#16#FFF7;
END_IF;
  IF xJogFwd[4] THEN
    wJogFwdReg := wJogFwdReg OR WORD#16#0008;
ELSE
    wJogFwdReg := wJogFwdReg AND WORD#16#FFF7;
END_IF;
  IF xJogRev[4] THEN
    wJogRevReg := wJogRevReg OR WORD#16#0008;
ELSE
    wJogRevReg := wJogRevReg AND WORD#16#FFF7;
END_IF;
  IF fbJogB.xReady THEN
    wJogReadyReg := wJogReadyReg OR WORD#16#0008;
ELSE
    wJogReadyReg := wJogReadyReg AND WORD#16#FFF7;
END_IF;
  IF fbJogB.xMoving THEN
    wJogMovingReg := wJogMovingReg OR WORD#16#0008;
ELSE
    wJogMovingReg := wJogMovingReg AND WORD#16#FFF7;
END_IF;
  IF fbJogB.xFault THEN
    wJogFaultReg := wJogFaultReg OR WORD#16#0008;
ELSE
    wJogFaultReg := wJogFaultReg AND WORD#16#FFF7;
END_IF;
  IF fbJogB.xJogError THEN
    wJogErrorReg := wJogErrorReg OR WORD#16#0008;
ELSE
    wJogErrorReg := wJogErrorReg AND WORD#16#FFF7;
END_IF;
  IF fbJogB.xJogAborted THEN
    wJogAbortedReg := wJogAbortedReg OR WORD#16#0008;
ELSE
    wJogAbortedReg := wJogAbortedReg AND WORD#16#FFF7;
END_IF;

// ================================
  // 5轴点动控制
  // ================================

  // 五轴总关闭时，点动功能块不会继续用本地 TRUE 保持上使能。

  // v26086：复位命令由 ModbusTcpSlave 从 arReg_data[89] 解析到 xJogReset[5]。
  // FB_ServoJog 内部用 R_TRIG 把这个 BOOL 转成 MC_Reset 上升沿。
  xResetCmdReg := xJogReset[5];

  xServoEnable := GVL.Axes[5].AxisEnable;

  fbJogC(
      Axis := AXIS_C,
      xServoOn := xServoEnable,
      xReset := xResetCmdReg,
      xJogFwd := xJogFwd[5],
      xJogRev := xJogRev[5],
      xLimitFwd := FALSE,
      xLimitRev := FALSE,
      lrJogVel := 100.0,
      lrAcc := 100.0,
      lrDec := 200.0,
      lrJerk := 0.0
  );


  // v26086：Jog 程序只写全局反馈位图，寄存器 arReg_data[90..99] 统一由 ModbusTcpSlave 写出。
  IF xResetCmdReg THEN
    wJogResetCmdReg := wJogResetCmdReg OR WORD#16#0010;
ELSE
    wJogResetCmdReg := wJogResetCmdReg AND WORD#16#FFEF;
END_IF;
  IF xJogMode[5] THEN
    wJogModeReg := wJogModeReg OR WORD#16#0010;
ELSE
    wJogModeReg := wJogModeReg AND WORD#16#FFEF;
END_IF;
  IF xJogFwd[5] THEN
    wJogFwdReg := wJogFwdReg OR WORD#16#0010;
ELSE
    wJogFwdReg := wJogFwdReg AND WORD#16#FFEF;
END_IF;
  IF xJogRev[5] THEN
    wJogRevReg := wJogRevReg OR WORD#16#0010;
ELSE
    wJogRevReg := wJogRevReg AND WORD#16#FFEF;
END_IF;
  IF fbJogC.xReady THEN
    wJogReadyReg := wJogReadyReg OR WORD#16#0010;
ELSE
    wJogReadyReg := wJogReadyReg AND WORD#16#FFEF;
END_IF;
  IF fbJogC.xMoving THEN
    wJogMovingReg := wJogMovingReg OR WORD#16#0010;
ELSE
    wJogMovingReg := wJogMovingReg AND WORD#16#FFEF;
END_IF;
  IF fbJogC.xFault THEN
    wJogFaultReg := wJogFaultReg OR WORD#16#0010;
ELSE
    wJogFaultReg := wJogFaultReg AND WORD#16#FFEF;
END_IF;
  IF fbJogC.xJogError THEN
    wJogErrorReg := wJogErrorReg OR WORD#16#0010;
ELSE
    wJogErrorReg := wJogErrorReg AND WORD#16#FFEF;
END_IF;
  IF fbJogC.xJogAborted THEN
    wJogAbortedReg := wJogAbortedReg OR WORD#16#0010;
ELSE
    wJogAbortedReg := wJogAbortedReg AND WORD#16#FFEF;
END_IF;

// ================================
// 日志映射部分：将当前未读日志填充到保持寄存器
// ================================
IF g_LogBuffer.count > 0 THEN
    // 获取当前读指针指向的日志条目
    pCurEntry := ADR(g_LogBuffer.entries[g_LogBuffer.readIdx]);
    sCurLog := pCurEntry^.sMessage;
    iLen := pCurEntry^.length;

    // 地址100：日志长度（WORD）
    arReg_data[100] := INT_TO_WORD(iLen);

    // 地址101-102：时间戳（低字，高字）
    arReg_data[101] := DWORD_TO_WORD(pCurEntry^.timestamp AND 16#FFFF);
    arReg_data[102] := DWORD_TO_WORD(SHR(pCurEntry^.timestamp, 16));

    // 清空字符串缓冲区寄存器（地址103 ~ 152，共50个WORD）
    FOR i := 103 TO 152 DO
        arReg_data[i] := 0;
    END_FOR

    // ----- 将字符串每两个字符打包成一个 WORD -----
    // 注意：你的环境中字符串索引从0开始（已验证）
    iCharIdx := 0;      // 当前字符索引（从0开始）
    iRegIdx := 103;     // 当前寄存器地址
    WHILE iCharIdx < iLen DO
        // 低字节 = 第一个字符
        wTemp := sCurLog[iCharIdx];
        iCharIdx := iCharIdx + 1;
        // 如果有下一个字符，放入高字节
        IF iCharIdx < iLen THEN
            wTemp := wTemp OR SHL(sCurLog[iCharIdx], 8);
            iCharIdx := iCharIdx + 1;
        END_IF
        arReg_data[iRegIdx] := wTemp;
        iRegIdx := iRegIdx + 1;
    END_WHILE
ELSE
    // 无未读日志，长度寄存器写0
    arReg_data[100] := 0;
END_IF

// --------------------------------
// 处理主站确认线圈（地址16）
// --------------------------------
IF arDo_data[16] THEN
    IF g_LogBuffer.count > 0 THEN
        g_LogBuffer.readIdx := (g_LogBuffer.readIdx + 1) MOD g_LogBuffer.maxSize;
        g_LogBuffer.count := g_LogBuffer.count - 1;
    END_IF
    arDo_data[16] := FALSE;
END_IF



IF isInit=FALSE THEN							

	modtcpslaveinit(en_in:=TRUE,					//Modbus TCP Slave初始化功能块使能
	xenable:=TRUE,									//使能初始化功能
	iport:=502,										//开放端口号502
	en_out=>eout,									//Modbus TCP Slave初始化功能块执行完成
	isocket=>iSocket,								//创建的socket存入变量
	uierror=>uiErr);								//Modbus TCP Slave初始化功能块执行错误信息

	IF isocket>=0 AND uiErr=0 THEN					//成功创建socket且无错误，逻辑标志置位，下周期执行ELSE
		isInit:=TRUE;	

		enCtr:=FALSE;
		ELSE                                        //等待连接成功
		modtcpslaveinit(en_in:=0,xenable:=0);	
	END_IF

ELSE



	// ============================================================
	// v26086 Modbus 寄存器集中处理区
	// 规则：所有 arReg_data/arAi_data 的地址读写都放在本程序，其他程序只写全局缓存变量。
	// ============================================================

	// arAi_data[1..5]：五轴当前位置反馈输入寄存器，X/Y/Z/B/C。
	// Python 按 0.1 单位读取；PLC 内部角度除以 aAngleFactor 后再乘 10。
	FOR i := 1 TO GVL.AXIS_COUNT DO
		arAi_data[i] := INT_TO_WORD(REAL_TO_INT(Axes[i].ActualAngle/aAngleFactor[i]*10.0));
	END_FOR

	// arAi_data[9]：五轴平台运行状态反馈，来自 FiveDOF_Platform_PRG 维护的 bfiveDOF_state。
	arAi_data[9]:=bfiveDOF_state;

	// arReg_data[0]：五轴绝对定位启动命令，非 0 时由 FiveDOF_Platform_PRG 触发运动。
	Move_5Axis_Sign:=arReg_data[0];

	// arReg_data[1..5]：五轴目标位置原始值，只有平台空闲时才更新目标，避免运动中目标被改写。
	IF 	bfiveDOF_state =0 THEN
		FOR i := 1 TO GVL.AXIS_COUNT DO
			dwAngle := WORD_TO_INT(arReg_data[i]);      // 有符号原始值
			PlatformTargetAngle[i] := dwAngle * aAngleFactor[i];
		END_FOR
	END_IF

	// arReg_data[32]：五轴总使能命令。0=关闭使能，非 0=打开使能。
	xEnableAllReg := arReg_data[32] <> 0;
	FOR i := 1 TO GVL.AXIS_COUNT DO
		GVL.Axes[i].AxisEnable := xEnableAllReg;
	END_FOR

	// arReg_data[48]：五轴使能请求反馈，bit0..bit4=X/Y/Z/B/C，bit15=五轴全部请求 TRUE。
	wEnableFeedbackReg := WORD#0;
	IF GVL.Axes[1].AxisEnable THEN wEnableFeedbackReg := wEnableFeedbackReg OR WORD#16#0001; END_IF;
	IF GVL.Axes[2].AxisEnable THEN wEnableFeedbackReg := wEnableFeedbackReg OR WORD#16#0002; END_IF;
	IF GVL.Axes[3].AxisEnable THEN wEnableFeedbackReg := wEnableFeedbackReg OR WORD#16#0004; END_IF;
	IF GVL.Axes[4].AxisEnable THEN wEnableFeedbackReg := wEnableFeedbackReg OR WORD#16#0008; END_IF;
	IF GVL.Axes[5].AxisEnable THEN wEnableFeedbackReg := wEnableFeedbackReg OR WORD#16#0010; END_IF;
	IF GVL.Axes[1].AxisEnable
	   AND GVL.Axes[2].AxisEnable
	   AND GVL.Axes[3].AxisEnable
	   AND GVL.Axes[4].AxisEnable
	   AND GVL.Axes[5].AxisEnable THEN
		wEnableFeedbackReg := wEnableFeedbackReg OR WORD#16#8000;
	END_IF;
	arReg_data[48] := WORD_TO_INT(wEnableFeedbackReg);

	// arReg_data[19]：点动总开关位图，bit0=X，bit1=Y，bit2=Z，bit3=B，bit4=C。
	xJogMode[1] := (arReg_data[19] AND WORD#16#0001) <> WORD#0; // X
	xJogMode[2] := (arReg_data[19] AND WORD#16#0002) <> WORD#0; // Y
	xJogMode[3] := (arReg_data[19] AND WORD#16#0004) <> WORD#0; // Z
	xJogMode[4] := (arReg_data[19] AND WORD#16#0008) <> WORD#0; // B
	xJogMode[5] := (arReg_data[19] AND WORD#16#0010) <> WORD#0; // C

	// arReg_data[6..15]：点动方向命令。方向必须同时满足 arReg_data[19] 对应轴点动总开关。
	xJogFwd[1] := xJogMode[1] AND (arReg_data[6] <> WORD#0);   // X 正向
	xJogRev[1] := xJogMode[1] AND (arReg_data[7] <> WORD#0);   // X 反向
	xJogFwd[2] := xJogMode[2] AND (arReg_data[8] <> WORD#0);   // Y 正向
	xJogRev[2] := xJogMode[2] AND (arReg_data[9] <> WORD#0);   // Y 反向
	xJogFwd[3] := xJogMode[3] AND (arReg_data[10] <> WORD#0);  // Z 正向
	xJogRev[3] := xJogMode[3] AND (arReg_data[11] <> WORD#0);  // Z 反向
	xJogFwd[4] := xJogMode[4] AND (arReg_data[12] <> WORD#0);  // B 正向
	xJogRev[4] := xJogMode[4] AND (arReg_data[13] <> WORD#0);  // B 反向
	xJogFwd[5] := xJogMode[5] AND (arReg_data[14] <> WORD#0);  // C 正向
	xJogRev[5] := xJogMode[5] AND (arReg_data[15] <> WORD#0);  // C 反向

	// arReg_data[89]：五轴复位命令位图，Python 写短脉冲，bit0..bit4=X/Y/Z/B/C。
	xJogReset[1] := (arReg_data[89] AND WORD#16#0001) <> WORD#0; // X 复位
	xJogReset[2] := (arReg_data[89] AND WORD#16#0002) <> WORD#0; // Y 复位
	xJogReset[3] := (arReg_data[89] AND WORD#16#0004) <> WORD#0; // Z 复位
	xJogReset[4] := (arReg_data[89] AND WORD#16#0008) <> WORD#0; // B 复位
	xJogReset[5] := (arReg_data[89] AND WORD#16#0010) <> WORD#0; // C 复位

	// arReg_data[33..37]：五轴状态字，来自 AxisStatusFeedback_PRG 写入的 wAxisStatusReg[1..5]。
	arReg_data[33] := WORD_TO_INT(wAxisStatusReg[1]); // X 状态字
	arReg_data[34] := WORD_TO_INT(wAxisStatusReg[2]); // Y 状态字
	arReg_data[35] := WORD_TO_INT(wAxisStatusReg[3]); // Z 状态字
	arReg_data[36] := WORD_TO_INT(wAxisStatusReg[4]); // B 状态字
	arReg_data[37] := WORD_TO_INT(wAxisStatusReg[5]); // C 状态字

	// arReg_data[38..47]：五轴 AxisErrorID，DWORD 拆成低 16 位和高 16 位。
	arReg_data[38] := WORD_TO_INT(DWORD_TO_WORD(dwAxisErrorIDReg[1]));
arReg_data[39] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwAxisErrorIDReg[1], 16)));
	arReg_data[40] := WORD_TO_INT(DWORD_TO_WORD(dwAxisErrorIDReg[2]));
arReg_data[41] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwAxisErrorIDReg[2], 16)));
	arReg_data[42] := WORD_TO_INT(DWORD_TO_WORD(dwAxisErrorIDReg[3]));
arReg_data[43] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwAxisErrorIDReg[3], 16)));
	arReg_data[44] := WORD_TO_INT(DWORD_TO_WORD(dwAxisErrorIDReg[4]));
arReg_data[45] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwAxisErrorIDReg[4], 16)));
	arReg_data[46] := WORD_TO_INT(DWORD_TO_WORD(dwAxisErrorIDReg[5]));
arReg_data[47] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwAxisErrorIDReg[5], 16)));

	// arReg_data[49..58]：五轴 MC_ReadStatus.ErrorID，DWORD 拆成低 16 位和高 16 位。
	arReg_data[49] := WORD_TO_INT(DWORD_TO_WORD(dwReadStatusErrorIDReg[1]));
arReg_data[50] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadStatusErrorIDReg[1], 16)));
	arReg_data[51] := WORD_TO_INT(DWORD_TO_WORD(dwReadStatusErrorIDReg[2]));
arReg_data[52] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadStatusErrorIDReg[2], 16)));
	arReg_data[53] := WORD_TO_INT(DWORD_TO_WORD(dwReadStatusErrorIDReg[3]));
arReg_data[54] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadStatusErrorIDReg[3], 16)));
	arReg_data[55] := WORD_TO_INT(DWORD_TO_WORD(dwReadStatusErrorIDReg[4]));
arReg_data[56] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadStatusErrorIDReg[4], 16)));
	arReg_data[57] := WORD_TO_INT(DWORD_TO_WORD(dwReadStatusErrorIDReg[5]));
arReg_data[58] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadStatusErrorIDReg[5], 16)));

	// arReg_data[59..68]：五轴 MC_ReadAxisError.ErrorID，DWORD 拆成低 16 位和高 16 位。
	arReg_data[59] := WORD_TO_INT(DWORD_TO_WORD(dwReadAxisErrorFBIDReg[1]));
arReg_data[60] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadAxisErrorFBIDReg[1], 16)));
	arReg_data[61] := WORD_TO_INT(DWORD_TO_WORD(dwReadAxisErrorFBIDReg[2]));
arReg_data[62] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadAxisErrorFBIDReg[2], 16)));
	arReg_data[63] := WORD_TO_INT(DWORD_TO_WORD(dwReadAxisErrorFBIDReg[3]));
arReg_data[64] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadAxisErrorFBIDReg[3], 16)));
	arReg_data[65] := WORD_TO_INT(DWORD_TO_WORD(dwReadAxisErrorFBIDReg[4]));
arReg_data[66] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadAxisErrorFBIDReg[4], 16)));
	arReg_data[67] := WORD_TO_INT(DWORD_TO_WORD(dwReadAxisErrorFBIDReg[5]));
arReg_data[68] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwReadAxisErrorFBIDReg[5], 16)));

	// arReg_data[69..78]：五轴 MC_Power.ErrorID，DWORD 拆成低 16 位和高 16 位。
	arReg_data[69] := WORD_TO_INT(DWORD_TO_WORD(dwPowerErrorIDReg[1]));
arReg_data[70] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwPowerErrorIDReg[1], 16)));
	arReg_data[71] := WORD_TO_INT(DWORD_TO_WORD(dwPowerErrorIDReg[2]));
arReg_data[72] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwPowerErrorIDReg[2], 16)));
	arReg_data[73] := WORD_TO_INT(DWORD_TO_WORD(dwPowerErrorIDReg[3]));
arReg_data[74] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwPowerErrorIDReg[3], 16)));
	arReg_data[75] := WORD_TO_INT(DWORD_TO_WORD(dwPowerErrorIDReg[4]));
arReg_data[76] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwPowerErrorIDReg[4], 16)));
	arReg_data[77] := WORD_TO_INT(DWORD_TO_WORD(dwPowerErrorIDReg[5]));
arReg_data[78] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwPowerErrorIDReg[5], 16)));

	// arReg_data[79..83]：五轴 MC_Power 诊断字，bit0=Status，bit1=Error。
	arReg_data[79] := WORD_TO_INT(wPowerDiagReg[1]); // X MC_Power 诊断
	arReg_data[80] := WORD_TO_INT(wPowerDiagReg[2]); // Y MC_Power 诊断
	arReg_data[81] := WORD_TO_INT(wPowerDiagReg[3]); // Z MC_Power 诊断
	arReg_data[82] := WORD_TO_INT(wPowerDiagReg[4]); // B MC_Power 诊断
	arReg_data[83] := WORD_TO_INT(wPowerDiagReg[5]); // C MC_Power 诊断

	// arReg_data[84..88]：轴状态诊断版本和汇总位图。
	arReg_data[84] := 26086;                              // 诊断版本号
	arReg_data[85] := WORD_TO_INT(wEnableMismatchReg);        // 使能请求不一致位图
	arReg_data[86] := WORD_TO_INT(wReadStatusErrorBitsReg);   // MC_ReadStatus.Error 位图
	arReg_data[87] := WORD_TO_INT(wReadAxisErrorBitsReg);     // MC_ReadAxisError.Error 位图
	arReg_data[88] := WORD_TO_INT(wReadStatusFBErrorBitsReg); // MC_ReadStatus.FBErrorOccured 位图

	// arReg_data[90..99]：点动/复位诊断反馈，全部由 Jog 程序写全局缓存，本程序统一输出到 Modbus。
	arReg_data[90] := WORD_TO_INT(wJogResetCmdReg); // 复位命令读到反馈
	arReg_data[91] := WORD_TO_INT(wJogModeReg);     // 点动总开关反馈
	arReg_data[92] := WORD_TO_INT(wJogFwdReg);      // 正向点动命令反馈
	arReg_data[93] := WORD_TO_INT(wJogRevReg);      // 反向点动命令反馈
	arReg_data[94] := WORD_TO_INT(wJogReadyReg);    // FB_ServoJog.xReady
	arReg_data[95] := WORD_TO_INT(wJogMovingReg);   // FB_ServoJog.xMoving
	arReg_data[96] := WORD_TO_INT(wJogFaultReg);    // FB_ServoJog.xFault
	arReg_data[97] := WORD_TO_INT(wJogErrorReg);    // FB_ServoJog.xJogError
	arReg_data[98] := WORD_TO_INT(wJogAbortedReg);  // FB_ServoJog.xJogAborted
	arReg_data[99] := 26086;                    // 点动/复位诊断版本号
	modtcpslavectrl(en_in:=enCtr,					//Modbus TCP Slave执行功能块使能
	xenable:=TRUE,									//Modbus TCP Slave执行功能使能
	isocket:=isocket,								//输入创建的socket
	dwatchdogtime:=2000,							//看门狗时间
	p_clientsocket:=ADR(arClient),					//将连接进来的socket存放到数组
	imaxclientcount:=10,							//设置最大连接数量
	uido_number:=17,uido_startaddr:=0,pdo_data:=ADR(arDo_data),		//uido_number设定线圈个数，uido_startaddr设定线圈起始地址，数据存放在arDo_data数组
	uidi_number:=16,uidi_startaddr:=0,pdi_data:=ADR(arDi_data),		//uidi_number设定离散型数据个数，uidi_startaddr设定离散型数据起始地址，数据存放在arDi_data数组
	uireg_number:=200,uireg_startaddr:=0,preg_data:=ADR(arReg_data), //uireg_number设定保持型寄存器个数，uireg_startaddr设定保持型寄存器起始地址，数据存放在arReg_data数组
	uiai_number:=16,uiai_startaddr:=0,pai_data:=ADR(arAi_data),		//uiai_number设定输入型寄存器个数，uiai_startaddr设定输入型寄存器起始地址，数据存放在arAi_data数组
	en_out=>eout,									//Modbus TCP Slave执行功能块执行完成
	uierror=>uierr);								//Modbus TCP Slave执行功能块执行错误信息
	enctr:=TRUE;
	IF uierr <>0 THEN                               //如果从站报错，则重新连接从站
		modtcpslaveinit(en_in:=0,xenable:=0);	
		isInit:=0;
	END_IF
END_IF


// 释放锁
g_LogLock := FALSE;
